import fs from 'node:fs';import {DatabaseSync} from 'node:sqlite';import {loadNewsRegistry} from './src/newsFlow/registry.mjs';import {registerOriginalSources} from './src/newsFlow/baomoiOriginalBranch.mjs';import {ThreeFlowState} from './src/newsFlow/threeFlowState.mjs';import {publicationHistoryUnconfirmed} from './src/web/newsOriginalPublicationContract.mjs';const root='/var/lib/news-flow/recovery-all-20261123',db=new DatabaseSync(root+'/audit.sqlite',{readOnly:true}),live=new DatabaseSync('/var/lib/news-flow/news-flow-runtime/write.sqlite',{readOnly:true}),registry=await loadNewsRegistry();registerOriginalSources(live,registry);ThreeFlowState.prototype.loadOverlays.call({db:live,configureSites:()=>{}},registry);const rows=db.prepare("SELECT c.site,c.url,s.id FROM cohort c JOIN stage_results s USING(parse_key) WHERE s.status='staged'").all(),hits=rows.filter(row=>publicationHistoryUnconfirmed(row.url,registry.sources.get(row.site)?.config));const r={at:new Date().toISOString(),staged:rows.length,historyBypasses:hits,verified:hits.length===0};fs.writeFileSync(root+'/history-quarantine-audit.json',JSON.stringify(r,null,2));console.log(JSON.stringify(r));db.close();live.close();
